{
  "summary": "Build an accessible search/filter header for a data table in the Northshore Clinical Portal workspace. Must include: (1) a search Input with an aria-label (or an associated Label) for screen readers, (2) an optional Select filter, and (3) a Button to clear/reset filters. Use shadcn-vue components and keep styling Tailwind-friendly.",
  "goals": [
    "Display data in a sortable/scannable table.",
    "Collect user input via forms.",
    "Provide search/filter controls for data views."
  ],
  "entities": [],
  "user_flows": [],
  "ui_needs": {
    "components": [
      {
        "name": "table",
        "reason": "Tabular data presentation"
      },
      {
        "name": "input",
        "reason": "Text inputs"
      },
      {
        "name": "select",
        "reason": "Discrete choices"
      }
    ],
    "charts": []
  },
  "constraints": {
    "styling": [
      "tailwindcss (assumed)"
    ],
    "framework": [
      "vue",
      "shadcn-vue"
    ]
  }
}

